const PAGE="<!doctype html><html lang=\"en\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><meta name=\"theme-color\" content=\"#15382d\"><title>My account · Sloth Mode</title><link rel=\"stylesheet\" href=\"/app.css\"><script src=\"/app.js\" defer></script></head>\n<body><div class=\"ambient\" aria-hidden=\"true\"></div><div class=\"shell\"><header class=\"top\"><a href=\"https://sloth.marceli.dev\" class=\"brand\"><span class=\"animal\">🦥</span><span>sloth<span class=\"muted-brand\">mode</span></span></a><nav><span class=\"beta\">ACCOUNT BETA</span><a href=\"https://sloth.marceli.dev/#connector\">Your workspace ↗</a></nav></header>\n<main><div class=\"intro\"><div><p class=\"eyebrow\">YOUR QUIET CORNER OF THE INTERNET</p><h1>One account.<br><em>Everywhere you work.</em></h1><p class=\"lead\">Link your own computer once. Keep Gemma and your notes local, while managing which devices you trust.</p></div><div class=\"identity\"><div class=\"avatar\" aria-hidden=\"true\">S</div><span>Signed in as</span><strong id=\"email\">Loading your account…</strong><span id=\"provider\">Verified with Cloudflare Access</span><div class=\"signedin\"><i></i> Account session active</div></div></div>\n<div class=\"stats\"><div class=\"stat\"><span>Linked devices</span><strong id=\"deviceCount\">—</strong><small>Only your computers</small></div><div class=\"stat\"><span>Local AI</span><strong>Private</strong><small>Gemma stays on your machine</small></div><div class=\"stat\"><span>Remote sync</span><strong>Off</strong><small>Cloud notes not enabled</small></div></div>\n<div class=\"columns\"><section class=\"panel primary\"><div class=\"panel-head\"><span class=\"label\">01 / DEVICES</span><span class=\"tag\">Revocable access</span></div><h2>Your trusted computers</h2><p class=\"support\">See linked connectors, check whether they are online, and revoke access to any device.</p><div id=\"devices\" class=\"devices\" aria-live=\"polite\"><p class=\"loading\">Loading devices…</p></div><div class=\"panel-actions\"><button id=\"newCode\" class=\"button primary-button\">+ Link a computer</button><button id=\"refresh\" class=\"button ghost\">Refresh</button></div><div id=\"linkBox\" class=\"linkbox\" hidden><div class=\"label\">ONE-TIME ENROLMENT CODE</div><div id=\"enrollCode\" class=\"code\" aria-label=\"One-time device code\"></div><div class=\"row\"><button id=\"copyCode\" class=\"button secondary-button\">Copy code</button><span id=\"expiry\" class=\"small\">Expires in 10 minutes</span></div><p>Open the Sloth Mode Connector setup window on your PC and paste this code under <strong>Link account</strong>. The connector never needs your Google or GitHub password.</p></div><p class=\"message\" id=\"message\" role=\"status\"></p></section>\n<section class=\"panel secondary\"><div class=\"panel-head\"><span class=\"label\">02 / YOUR PRIVACY</span><span class=\"dot\"></span></div><h2>The sloth promise.</h2><p class=\"support\">Sloth Mode has two separate connections. You choose when to use them.</p><div class=\"privacy-item\"><span class=\"privacy-icon\">⌂</span><div><strong>Local pairing</strong><p>Your browser and home computer communicate directly. Your notes never cross the internet.</p></div></div><div class=\"privacy-item\"><span class=\"privacy-icon\">↗</span><div><strong>Account-linked devices</strong><p>Cloudflare stores a device name, token hash and last-seen timestamp. Not your tasks or prompts.</p></div></div><div class=\"privacy-item\"><span class=\"privacy-icon\">☁</span><div><strong>Remote access</strong><p>Not yet enabled. A later opt-in feature will connect to your PC securely while away.</p></div></div><div class=\"privacy-item\"><span class=\"privacy-icon\">✓</span><div><strong>Your account, your control</strong><p>Revoke a connector at any time. Its local task data stays on that PC.</p></div></div></section></div>\n<footer><span>🦥 SLOW AND STEADY · LOCAL FIRST</span><span>Sloth Mode account preview · Secure Google / GitHub / email login via Cloudflare Access</span></footer></main></div></body></html>\n";
const APP_CSS=":root{font-family:Inter,ui-sans-serif,system-ui,-apple-system,Segoe UI,sans-serif;background:#0b211a;color:#f1f6e7;font-synthesis:none}*{box-sizing:border-box}body{margin:0;min-width:0;overflow-x:hidden}.ambient{position:fixed;inset:0;z-index:-1;background:radial-gradient(ellipse at 80% 0%,#285c4220,transparent 52%),radial-gradient(ellipse at 0% 65%,#6d8c3830,transparent 48%),#0b211a}.shell{max-width:1370px;margin:auto;padding:0 clamp(18px,4vw,58px)}a{color:inherit;text-decoration:none}.top{display:flex;align-items:center;justify-content:space-between;gap:18px;padding:25px 0;border-bottom:1px solid #627c6650}.brand{display:flex;align-items:center;gap:12px;font-size:26px;font-weight:840;letter-spacing:-1.7px;white-space:nowrap}.animal{font-size:33px}.muted-brand{color:#b3dba1}.top nav{display:flex;align-items:center;gap:24px;font-size:13px;font-weight:660}.top nav a{color:#d5eabc;border-bottom:1px solid transparent;padding:10px 0}.top nav a:hover{border-color:#d5eabc}.beta{font-size:10px;letter-spacing:1.5px;color:#b8e8a7;border:1px solid #7592706a;padding:8px 12px;border-radius:30px}.intro{display:grid;grid-template-columns:minmax(0,1.3fr) minmax(270px,.65fr);gap:clamp(24px,7vw,90px);align-items:center;padding:clamp(42px,6vw,83px) 0 clamp(36px,6vw,80px)}.eyebrow,.label{font-weight:790;font-size:10px;letter-spacing:2px;color:#c5e8a2}.intro h1{font-size:clamp(45px,5.8vw,91px);letter-spacing:-.065em;line-height:.99;margin:20px 0 22px;max-width:850px}.intro h1 em{color:#c4e897;font-style:normal}.lead{font-size:clamp(15px,1.3vw,18px);line-height:1.65;color:#b6cabb;max-width:560px;margin:0}.identity{background:linear-gradient(142deg,#193c2f,#143326);border:1px solid #50775b7c;border-radius:27px;box-shadow:0 16px 65px #030f0b6b;min-width:0;padding:30px;display:flex;flex-direction:column;align-items:flex-start;gap:6px}.avatar{width:53px;height:53px;display:grid;place-items:center;background:#d0eeb1;color:#15382c;border-radius:18px;font-size:27px;font-weight:800;margin-bottom:16px}.identity span{font-size:12px;color:#a5c1ae}.identity strong{font-size:clamp(14px,1.4vw,18px);overflow-wrap:anywhere;line-height:1.5}.signedin{margin-top:19px;border-radius:30px;padding:9px 12px;background:#346a4765;color:#d6f3bb;font-size:11px}.signedin i{display:inline-block;background:#a4eaa9;width:8px;height:8px;border-radius:50%;margin-right:7px;box-shadow:0 0 0 4px #a4eaa91c}.stats{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:15px}.stat{min-width:0;padding:23px 25px;background:#19392cb3;border:1px solid #5a785867;border-radius:19px;display:flex;flex-direction:column;gap:10px}.stat span{font-size:12px;color:#b9d4bb}.stat strong{font-size:clamp(25px,2.4vw,35px);letter-spacing:-1.6px}.stat small{font-size:11px;color:#a0b8a2}.columns{display:grid;grid-template-columns:minmax(0,1.15fr) minmax(0,.85fr);gap:19px;margin:22px 0 54px;align-items:start}.panel{min-width:0;border-radius:24px;padding:clamp(22px,3vw,35px);border:1px solid #5a785867;background:#17372b}.secondary{background:#102c23}.panel-head{display:flex;justify-content:space-between;align-items:center;gap:10px}.tag{border:1px solid #749a7993;padding:6px 11px;font-size:10px;border-radius:30px;color:#cce3bf}.panel h2{font-size:clamp(24px,3vw,33px);letter-spacing:-1.35px;margin:20px 0 7px}.support{line-height:1.63;color:#b5ccbd;font-size:13px;margin:0 0 25px}.devices{min-height:90px;display:grid;gap:11px}.device{display:flex;align-items:center;gap:14px;background:#224b36;border:1px solid #5f8061aa;padding:16px;border-radius:14px;min-width:0}.device-icon{display:grid;place-items:center;border-radius:12px;background:#3b7050;color:#dbf5c1;font-size:22px;width:46px;height:46px;flex:none}.device-meta{flex:1;min-width:0}.device-name{font-weight:700;font-size:13px;overflow-wrap:anywhere}.device-detail{font-size:11px;line-height:1.7;color:#b4c7b3}.device button{border:1px solid #bba77d88;color:#ffdbb8;background:transparent;border-radius:9px;padding:9px 10px;cursor:pointer;font-size:11px}.device button:hover{background:#683e2c}.loading{font-size:12px;color:#b8cdb8}.empty{text-align:center;background:#214631;border:1px dashed #83a27f;padding:25px 18px;border-radius:14px;color:#d0e9cb}.empty strong{display:block;margin:6px;font-size:16px}.empty p{margin:5px;color:#b4c8b2;line-height:1.6;font-size:12px}.panel-actions{display:flex;flex-wrap:wrap;gap:10px;margin-top:22px}.button{border:1px solid #658769;cursor:pointer;font:inherit;font-size:12px;font-weight:700;padding:13px 19px;border-radius:12px;transition:transform .18s ease,background .18s ease;min-height:43px}.button:hover{transform:translateY(-2px)}.button:active{transform:translateY(0)}.primary-button{background:#d2edb0;color:#18362b;border-color:transparent}.ghost{background:transparent;color:#d7e9d0}.secondary-button{background:#bce5a3;color:#133c29;border:0}.button:focus-visible,a:focus-visible{outline:3px solid #cbecc2;outline-offset:3px}.linkbox{margin-top:22px;background:#0b271e;padding:23px;border-radius:15px;border:1px solid #739171}.code{font:800 clamp(21px,3.7vw,29px)/1.4 ui-monospace,SFMono-Regular,Consolas,monospace;letter-spacing:.055em;margin:14px 0;overflow-wrap:anywhere;color:#d5f1a8}.row{display:flex;gap:15px;align-items:center;flex-wrap:wrap}.small{font-size:11px;color:#d1e8c4}.linkbox p{font-size:12px;color:#bad1c2;line-height:1.65}.message{font-size:12px;line-height:1.5;min-height:1.2em;color:#c4e8b4}.privacy-item{display:flex;gap:15px;padding:17px 0;border-top:1px solid #54725e4d}.privacy-icon{width:33px;height:33px;border-radius:10px;display:grid;place-items:center;font-size:22px;color:#b6e6a2;background:#244734;flex:none}.privacy-item strong{font-size:13px}.privacy-item p{font-size:12px;color:#afc5b4;line-height:1.65;margin:6px 0 0}.dot{width:9px;height:9px;border-radius:50%;background:#9cdda4;box-shadow:0 0 0 4px #9cdda421}footer{display:flex;justify-content:space-between;gap:12px;flex-wrap:wrap;padding:23px 0 30px;border-top:1px solid #4865507b;color:#9bb49f;font-size:10px;line-height:1.7}button[disabled]{opacity:.55;cursor:wait}[hidden]{display:none!important}@media(max-width:960px){.intro{gap:28px}.columns{grid-template-columns:1fr}.secondary{order:2}}@media(max-width:680px){.intro{grid-template-columns:1fr}.identity{padding:23px}.intro h1{font-size:clamp(44px,11vw,68px)}.stats{grid-template-columns:1fr}.stat{padding:17px 21px;gap:3px}.stat strong{font-size:27px}.columns{gap:14px}.top nav{gap:11px}.beta{display:none}}@media(max-width:370px){.top nav a{font-size:11px}.brand{font-size:20px}.animal{font-size:25px}.panel{padding:19px}.device{flex-wrap:wrap}.device button{margin-left:59px}}@media(prefers-reduced-motion:reduce){*,*::before,*::after{scroll-behavior:auto!important;animation:none!important;transition:none!important}}\n";
const APP_JS="'use strict';\nconst $=id=>document.getElementById(id);\nconst formatTime=ts=>ts?new Date(ts*1000).toLocaleString():null;\nasync function api(path,init={}){const r=await fetch(path,{credentials:'same-origin',...init,headers:{...(init.body?{'Content-Type':'application/json'}:{}),...(init.headers||{})}});let value;try{value=await r.json()}catch{throw Error('Server returned an unexpected response')}if(!r.ok)throw Error(value.error||'Request failed');return value}\nfunction status(message,bad=false){$('message').textContent=message;$('message').style.color=bad?'#ffd2b7':'#c4e8b4'}\nfunction renderDevices(data){const root=$('devices');root.replaceChildren();$('deviceCount').textContent=String(data.devices.length);if(!data.devices.length){const card=document.createElement('div');card.className='empty';const strong=document.createElement('strong');strong.textContent='No linked computers yet';const p=document.createElement('p');p.textContent='Link your first Sloth Mode Connector to see it here.';card.append(strong,p);root.append(card);return}for(const d of data.devices){const card=document.createElement('article');card.className='device';const icon=document.createElement('div');icon.className='device-icon';icon.textContent='▣';const details=document.createElement('div');details.className='device-meta';const name=document.createElement('div');name.className='device-name';name.textContent=d.label;const info=document.createElement('div');info.className='device-detail';info.textContent=d.revoked_at?`Revoked ${formatTime(d.revoked_at)}`:d.last_seen_at?`Last seen ${formatTime(d.last_seen_at)}`:'Linked, waiting for first heartbeat';details.append(name,info);card.append(icon,details);if(!d.revoked_at){const button=document.createElement('button');button.textContent='Revoke';button.setAttribute('aria-label','Revoke '+d.label);button.onclick=async()=>{if(!confirm(`Revoke “${d.label}” from this account? Its local notes will remain on that PC.`))return;button.disabled=true;try{await api('/v1/devices/revoke',{method:'POST',body:JSON.stringify({device_id:d.device_id})});status('Device revoked. It will no longer authenticate to the account service.');await loadDevices()}catch(e){status(e.message,true)}finally{button.disabled=false}};card.append(button)}root.append(card)}}\nasync function loadDevices(){try{renderDevices(await api('/v1/devices'))}catch(e){status(e.message,true);$('devices').textContent='Unable to load devices.'}}\nlet validUntil=0;\nasync function createCode(){const btn=$('newCode');btn.disabled=true;try{const value=await api('/v1/link-codes',{method:'POST',body:'{}'});$('linkBox').hidden=false;$('enrollCode').textContent=value.code;validUntil=Date.now()+value.expires_in*1000;status('One-time code ready. Only enter it in your own computer’s Sloth Mode Connector.');$('copyCode').focus()}catch(e){status(e.message,true)}finally{btn.disabled=false}}\nfunction updateExpiry(){if(!validUntil)return;const seconds=Math.max(0,Math.ceil((validUntil-Date.now())/1000));$('expiry').textContent=seconds?`Expires in ${Math.ceil(seconds/60)} minute${Math.ceil(seconds/60)===1?'':'s'}`:'Expired — generate a new code';if(!seconds)$('copyCode').disabled=true}\nasync function copyCode(){const value=$('enrollCode').textContent;try{await navigator.clipboard.writeText(value);status('Code copied. It expires shortly and works only once.')}catch{status('Select the code above and copy it manually.',true)}}\nasync function setup(){try{const me=await api('/v1/me');$('email').textContent=me.email;let prov=typeof me.provider==='string'?me.provider:'Cloudflare Access';$('provider').textContent='Verified via '+prov}catch(e){$('email').textContent='Unable to read account';status(e.message,true)}await loadDevices();$('newCode').onclick=createCode;$('refresh').onclick=loadDevices;$('copyCode').onclick=copyCode;setInterval(updateExpiry,10000);setInterval(loadDevices,45000)}\nsetup();\n";
export default service;
